mapper.select:
select view_id as viewId, view_name as viewName, view_type as viewType, analysis_tpl_id as analysisTplId, analysis_tpl_cfg_id as analysisTplCfgId, is_active as isActive, sort_id as sortId, created_by as createdBy, created_time as createdTime, updated_by as updatedBy, updated_time as updatedTime from ssm_analysis_tpl_view where 1 = 1
and analysis_tpl_id = #{analysisTplId}
and view_type = #{viewType}
and created_by = #{createdBy}
and is_active = 1 order by sort_id asc

select ifnull(max(sort_id), 0) + 1
from ssm_analysis_tpl_view
where analysis_tpl_id = #{analysisTplId}

mapper.update:
update
    ssm_analysis_tpl_view
set
    sort_id = sort_id + 1,
    updated_time = now(),
    updated_by = #{userName}
where
    analysis_tpl_id = #{analysisTplId}
    and is_active = 1


        and sort_id > #{sortId}


        and sort_id >= #{sortId}
